import sys

data = sys.stdin.read().split()
r, c, k = int(data[0]), int(data[1]), int(data[2])
g = [[int(data[3 + i * c + j]) for j in range(c)] for i in range(r)]
INF = 10 ** 9
dist = [[[INF] * (k + 1) for _ in range(c)] for _ in range(r)]
dist[0][0][0] = 0
changed = True
while changed:
    changed = False
    for x in range(r):
        for y in range(c):
            for j in range(k + 1):
                d = dist[x][y][j]
                if d >= INF:
                    continue
                for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nx, ny = x + dx, y + dy
                    if 0 <= nx < r and 0 <= ny < c:
                        nj = j + g[nx][ny]
                        if nj <= k and d + 1 < dist[nx][ny][nj]:
                            dist[nx][ny][nj] = d + 1
                            changed = True
best = min(dist[r - 1][c - 1])
print(best if best < INF else -1)

